import { setAOhost } from "../../client/aoHost";
import { client } from "../../client";
import { renderPlayerList } from "../../dom/renderPlayerList";

/**
 * new asset url!!
 * @param {Array} args packet arguments
 */
export const handleASS = (args: string[]) => {
  if (args[1] !== "None") {
    setAOhost(args[1]);
    // Resources (shout bubbles/sfx, testimony/guilty splashes, etc.) were
    // built against the default attorneyoffline.de asset base at client
    // construction time, before we knew the server's real asset host.
    // Rebuild them now that AO_HOST points at the right place.
    client.refreshResources();
  }
  renderPlayerList();
};
