/**
 * Upgrades a `ws://` connection string to `wss://` when the page itself is
 * served over https. Browsers refuse to open a plain ws:// connection from
 * an https:// page (mixed content), so a plain alert-and-fail here was
 * strictly worse than attempting wss:// - if the server has TLS set up
 * (e.g. behind a reverse proxy), the upgrade lets the connection succeed;
 * if it doesn't, the connection fails the same way ws:// would have anyway.
 * @param {string} connectionString the connection string to check
 */
export function upgradeWsProtocol(connectionString: string): string {
  if (
    window.location.protocol === "https:" &&
    connectionString.startsWith("ws://")
  ) {
    console.log("Upgrading websocket connection to wss");
    return connectionString.replace("ws://", "wss://");
  }
  return connectionString;
}
